// Compact binary vehicle snapshots, shared by the multiplayer server and the browser game.
// The browser copy at public/rc-crawler/vendor/net/codec.js is generated by `npm run vendor` — edit this one.
//
// Movement is the only high-frequency traffic, so it is packed by hand (little-endian) instead of going
// through JSON / msgpack: 35 bytes per client update, 36 bytes per vehicle in a server snapshot.
//
//   pose    f32 x, y, z                 world metres
//           i16 qx, qy, qz, qw          unit quaternion * 32767
//           i16 vx, vy, vz              linear velocity, cm/s
//           i8  steer                   front wheel angle / MAX_STEER * 127
//           i8  throttle                -1..1 * 127
//           u8  hub[4]                  suspension hub height (local y), see HUB_LO / HUB_RANGE
//           u8  flags                   see FLAG

export const MOVE_BYTES = 35;          // client -> server: u16 seq + pose (33)
export const POSE_BYTES = 33;
export const ENTRY_BYTES = 3 + POSE_BYTES; // server -> clients: u8 slot + u16 age (ms since the server received it) + pose
export const MAX_STEER = 0.6;
export const HUB_LO = -0.25, HUB_RANGE = 0.3;
export const FLAG = { LIGHTS: 1, BRAKE: 2, ROLLED: 4, AIR: 8, RECOVER: 16, HIGH: 32, DIG: 64 };

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);

function writePose(dv, o, s) {
  dv.setFloat32(o, s.x, true); dv.setFloat32(o + 4, s.y, true); dv.setFloat32(o + 8, s.z, true);
  dv.setInt16(o + 12, Math.round(clamp(s.qx, -1, 1) * 32767), true);
  dv.setInt16(o + 14, Math.round(clamp(s.qy, -1, 1) * 32767), true);
  dv.setInt16(o + 16, Math.round(clamp(s.qz, -1, 1) * 32767), true);
  dv.setInt16(o + 18, Math.round(clamp(s.qw, -1, 1) * 32767), true);
  dv.setInt16(o + 20, Math.round(clamp(s.vx * 100, -32767, 32767)), true);
  dv.setInt16(o + 22, Math.round(clamp(s.vy * 100, -32767, 32767)), true);
  dv.setInt16(o + 24, Math.round(clamp(s.vz * 100, -32767, 32767)), true);
  dv.setInt8(o + 26, Math.round(clamp(s.steer / MAX_STEER, -1, 1) * 127));
  dv.setInt8(o + 27, Math.round(clamp(s.throttle, -1, 1) * 127));
  for (let i = 0; i < 4; i++) dv.setUint8(o + 28 + i, Math.round(clamp((s.hub[i] - HUB_LO) / HUB_RANGE, 0, 1) * 255));
  dv.setUint8(o + 32, s.flags & 255);
}

function readPose(dv, o, s) {
  s.x = dv.getFloat32(o, true); s.y = dv.getFloat32(o + 4, true); s.z = dv.getFloat32(o + 8, true);
  s.qx = dv.getInt16(o + 12, true) / 32767; s.qy = dv.getInt16(o + 14, true) / 32767;
  s.qz = dv.getInt16(o + 16, true) / 32767; s.qw = dv.getInt16(o + 18, true) / 32767;
  const n = Math.hypot(s.qx, s.qy, s.qz, s.qw) || 1;
  s.qx /= n; s.qy /= n; s.qz /= n; s.qw /= n;
  s.vx = dv.getInt16(o + 20, true) / 100; s.vy = dv.getInt16(o + 22, true) / 100; s.vz = dv.getInt16(o + 24, true) / 100;
  s.steer = (dv.getInt8(o + 26) / 127) * MAX_STEER;
  s.throttle = dv.getInt8(o + 27) / 127;
  s.hub = s.hub || [0, 0, 0, 0];
  for (let i = 0; i < 4; i++) s.hub[i] = HUB_LO + (dv.getUint8(o + 28 + i) / 255) * HUB_RANGE;
  s.flags = dv.getUint8(o + 32);
  return s;
}

const view = (bytes) => new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);

/** client -> server movement update */
export function encodeMove(seq, s, out = new Uint8Array(MOVE_BYTES)) {
  const dv = view(out);
  dv.setUint16(0, seq & 0xffff, true);
  writePose(dv, 2, s);
  return out;
}
export function decodeMove(bytes, s = {}) {
  if (!bytes || bytes.byteLength !== MOVE_BYTES) return null;
  const dv = view(bytes);
  s.seq = dv.getUint16(0, true);
  return readPose(dv, 2, s);
}

/** server -> clients: every vehicle's latest accepted pose. The packet carries the server time (ms) and
 *  each pose its age, so a pose is placed at the moment it reached the server, not when it was rebroadcast
 *  (an unchanged pose sent twice keeps one timestamp instead of looking like the truck stopped). */
export function encodeSnapshot(time, entries) {
  const out = new Uint8Array(9 + entries.length * ENTRY_BYTES);
  const dv = view(out);
  dv.setFloat64(0, time, true);
  dv.setUint8(8, entries.length);
  let o = 9;
  for (const e of entries) { dv.setUint8(o, e.slot); dv.setUint16(o + 1, clamp(Math.round(time - e.t), 0, 65535), true); writePose(dv, o + 3, e); o += ENTRY_BYTES; }
  return out;
}
/** calls fn(slot, pose, poseTime) per vehicle; returns the server time, or null for a malformed packet */
export function decodeSnapshot(bytes, fn, scratch = {}) {
  if (!bytes || bytes.byteLength < 9) return null;
  const dv = view(bytes);
  const time = dv.getFloat64(0, true), n = dv.getUint8(8);
  if (bytes.byteLength !== 9 + n * ENTRY_BYTES) return null;
  let o = 9;
  for (let i = 0; i < n; i++) { fn(dv.getUint8(o), readPose(dv, o + 3, scratch), time - dv.getUint16(o + 1, true)); o += ENTRY_BYTES; }
  return time;
}

/** finite, normalised, within the map and physically plausible on its own (not against history) */
export function poseSane(s, bound = 72) {
  for (const k of ['x', 'y', 'z', 'qx', 'qy', 'qz', 'qw', 'vx', 'vy', 'vz', 'steer', 'throttle']) if (!Number.isFinite(s[k])) return false;
  if (Math.abs(s.x) > bound || Math.abs(s.z) > bound || s.y < -40 || s.y > 160) return false;
  if (Math.hypot(s.vx, s.vy, s.vz) > 80) return false;
  return true;
}
